type Org = {
  id: string;
  [key: string]: unknown;
};

type User = {
  id: string;
  orgId: string;
  org?: Org;
};

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status} for ${url}`);
  }
  return (await response.json()) as T;
}

export async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

export async function loadUsers(ids: string[]): Promise<User[]> {
  return await Promise.all(ids.map((id) => loadUser(id)));
}

interface Org {
  id: string | number;
  name?: string;
  [key: string]: unknown;
}

interface User {
  id: string | number;
  orgId: string | number;
  org?: Org;
  [key: string]: unknown;
}

async function ensureOk(response: Response, context: string): Promise<Response> {
  if (!response.ok) {
    throw new Error(`${context} failed with status ${response.status}`);
  }
  return response;
}

export async function loadUser(id: string | number): Promise<User> {
  const userResponse = await fetch(`/api/users/${encodeURIComponent(String(id))}`);
  await ensureOk(userResponse, `loadUser(${id})`);
  const user = (await userResponse.json()) as User;

  const orgResponse = await fetch(`/api/orgs/${encodeURIComponent(String(user.orgId))}`);
  await ensureOk(orgResponse, `loadOrg(${user.orgId})`);
  const org = (await orgResponse.json()) as Org;

  return { ...user, org };
}

export async function loadUsers(ids: Array<string | number>): Promise<User[]> {
  if (ids.length === 0) {
    return [];
  }
  return Promise.all(ids.map((id) => loadUser(id)));
}

- `Rc<RefCell<T>>`: single-threaded shared ownership + interior mutability. Cheap, but not `Send`/`Sync`; borrow rules enforced at runtime (`RefCell` can panic). Use for graphs, caches, UI/event trees in one thread.
- `Arc<Mutex<T>>`: thread-safe shared ownership + exclusive mutable access via locking. Atomic refcount, `Send`/`Sync` if `T: Send`; can block/deadlock. Use for shared state across threads.

```rust
use std::rc::Rc;
use std::cell::RefCell;

let shared = Rc::new(RefCell::new(0));
let a = shared.clone();
*a.borrow_mut() += 1; // single-threaded
```

```rust
use std::sync::{Arc, Mutex};
use std::thread;

let shared = Arc::new(Mutex::new(0));
let b = shared.clone();
thread::spawn(move || {
    *b.lock().unwrap() += 1; // multi-threaded
});
```

Rule of thumb: one thread → `Rc<RefCell<T>>`; across threads → `Arc<Mutex<T>>`.

- `Rc<RefCell<T>>`: single-threaded shared ownership + runtime-checked interior mutability. Cheap, but not `Send`/`Sync`; borrow conflicts panic. Use for UI/event loops, graphs, caches in one thread.
- `Arc<Mutex<T>>`: thread-safe shared ownership + exclusive mutable access via locking. Atomic refcount and lock overhead; use across threads. `Mutex` blocks/waits rather than panicking on contention.

```rust
use std::rc::Rc;
use std::cell::RefCell;

let x = Rc::new(RefCell::new(5));
*x.borrow_mut() += 1; // single-threaded
```

```rust
use std::sync::{Arc, Mutex};
use std::thread;

let x = Arc::new(Mutex::new(5));
let y = Arc::clone(&x);
thread::spawn(move || {
    *y.lock().unwrap() += 1;
});
```

Rule of thumb: one thread → `Rc<RefCell<T>>`; multiple threads → `Arc<Mutex<T>>`.
